mapper.select:
SELECT ag.anime_id AS animeId, g.genre_id AS genreId, g.genre_kor AS genreName FROM Genres AS g JOIN AnimeGenres AS ag ON g.genre_id = ag.genre_id WHERE 1 = 1
AND ag.anime_id IN
#{animeId}

SELECT DISTINCT(a.anime_id) AS animeId, a.title_kor_manual AS titleMan, a.title_kor AS titleKor, a.title_english AS titleEng, a.title_romaj AS titleRom, a.title_native AS titleNat, a.cover_image_url AS coverImageUrl, a.popularity AS popularity FROM Anime AS a JOIN AnimeGenres AS ag ON a.anime_id = ag.anime_id WHERE 1 = 1
AND ag.genre_id = #{genreId}
AND a.popularity < #{lastId}
AND NOT EXISTS( SELECT 1 FROM AnimeGenres as ag2 WHERE ag2.anime_id = a.anime_id AND ag2.genre_id = 638 )
AND a.start_date BETWEEN #{startDate} AND #{endDate}
ORDER BY a.popularity DESC LIMIT #{size}

SELECT DISTINCT(a.anime_id) AS animeId, a.title_kor_manual AS titleMan, a.title_kor AS titleKor, a.title_english AS titleEng, a.title_romaj AS titleRom, a.title_native AS titleNat, a.cover_image_url AS coverImageUrl, a.popularity AS popularity FROM Anime AS a JOIN AnimeGenres AS ag ON a.anime_id = ag.anime_id WHERE 1 = 1
AND ag.genre_id = #{genreId}
AND a.popularity < #{lastId}
AND NOT EXISTS( SELECT 1 FROM AnimeGenres as ag2 WHERE ag2.anime_id = a.anime_id AND ag2.genre_id = 638 ) ORDER BY a.popularity DESC LIMIT #{size}
